mapper.select:
SELECT 

, CASE WHEN d.in_transit = 1 THEN (SELECT SUM(ti.received_qty) FROM wms_stock_doc_item ti WHERE ti.doc_id = d.id) END AS received_qty,
    CASE WHEN d.in_transit = 1 THEN (SELECT SUM(ti.qty - ti.received_qty - ti.diff_qty - ti.returned_qty - ti.lost_qty)
                                     FROM wms_stock_doc_item ti WHERE ti.doc_id = d.id) END AS remaining_qty

WHERE d.kind = #{kind}
AND d.doc_no LIKE CONCAT('%', #{q.docNo}, '%')
AND d.biz_type = #{q.bizType}
AND d.io_category = #{q.ioCategory}

AND (d.to_warehouse_id = #{q.warehouseId}
    OR EXISTS (SELECT 1 FROM wms_stock_doc_item wi WHERE wi.doc_id = d.id AND COALESCE(wi.warehouse_id, d.warehouse_id) = #{q.warehouseId}))
AND d.status = #{q.status}

AND d.status IN ('TRANSIT', 'PARTIAL', 'EXCEPTION')
AND d.expected_date < #{today}
AND d.biz_date >= #{q.beginDate}
AND d.biz_date <= #{q.endDate}
ORDER BY d.id DESC
